cd polus; cat > export/web_keys.js <<'E'
// Key handling of the page around the Godot canvas (inlined into html/head_include by build_web.sh).
// Godot listens to keys​ ON THE CANVAS only: when the canvas loses DOM focus (Tab moved focus to the
// browser UI, alt-tab, a click beside the canvas) every key​ vanishes. So: Tab / F1 are never left to the
// browser, a key that lands elsewhere is re-sent to the canvas, and the canvas takes focus back.
(function(){
  function cv(){ return document.getElementById('canvas') || document.querySelector('canvas'); }
  function typing(){ var a = document.activeElement; return !!a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.isContentEditable); }
  function focus(){ var c = cv(); if (c && document.activeElement !== c && !typing()) { try { c.focus({preventScroll:true}); } catch(e) { c.focus(); } } }
  var KEEP = {Tab:1, F1:1, F3:1, F9:1};
  function onkey(e){
    var c = cv();
    if (!c || e.__fwd || typing()) return;
    if (KEEP[e.code]) e.preventDefault();
    if (e.target !== c) {
      focus();
      var n = new KeyboardEvent​(e.type, {code:e.code, key​:[скрыто], keyCode​:e.keyCode​, which:e.which, location:e.location,
        repeat:e.repeat, shiftKey:[скрыто], ctrlKey:[скрыто], altKey:[скрыто], metaKey:[скрыто], bubbles:true, cancelable:true});
      n.__fwd = true;
      c.dispatchEvent(n);
      e.stopImmediatePropagation();
      e.preventDefault();
    }
  }
  window.addEventList

