extends Node
## task 59 perf: cost of RockNode.inside / SolidGrid.contains on boulders (and the voxel shortcut's answers vs the exact path).

func _ready() -> void:
	for sz: float in [0.6, 1.2, 2.0]:
		var r := RockNode.new()
		r.setup(900 + int(sz * 10), "granite", 77, Basis().scaled(Vector3(sz, sz * 0.7, sz * 0.9)))
		add_child(r)
		var cells := r.cells()
		var tris := 0
		for c: CpuMesh in cells:
			tris += StoneMesh.tris(c).size() / 3
		var box := r.bounds()
		var t0 := Time.get_ticks_usec()
		for c: CpuMesh in cells:
			SolidGrid.of(c)
		var build := (Time.get_ticks_usec() - t0) / 1000.0
		var rng := RandomNumberGenerator.new()
		rng.seed = 5
		var pts := PackedVector3Array()
		for i in 20000:
			pts.append(box.position + Vector3(rng.randf(), rng.randf(), rng.randf()) * box.size)
		t0 = Time.get_ticks_usec()
		var nin := 0
		for p in pts:
			if RockNode.inside(cells, p):
				nin += 1
		var us := float(Time.get_ticks_usec() - t0) / pts.size()
		var mism := 0
		var exact_us := 0.0
		if SolidGrid.new().has_method("contains_exact"):
			t0 = Time.get_ticks_usec()
			for p in pts:
				var e := false
				for c: CpuMesh in cells:
					if c.get_aabb().has_point(p) and SolidGrid.of(c).contains_exact(p):
						e = true
						break
				if e != RockNode.inside(cells, p):
					mism += 1
			exact_us = float(Time.get_ticks_usec() - t0) / pts.size()
		print("GRIDBENCH size=%.1f cells=%d tris=%d grid_build=%.1f ms inside=%.2f us/call (in %d/%d) mismatch=%d exact+fast=%.2f us" % [sz, cells.size(), tris, build, us, nin, pts.size(), mism, exact_us])
	get_tree().quit()
EOF
