## (task 59 perf) RockNode.inside(cells, inv * p) as a Callable(world p) -> bool, the same answer, without
## looking the pieces' boxes and grids up per call (their SolidGrid voxels answer most points).
static func solid_fn(cells: Array, inv: Transform3D) -> Callable:
	var grids: Array[SolidGrid] = []
	var bxs: Array[AABB] = []
	for c: CpuMesh in cells:
		grids.append(SolidGrid.of(c))
		bxs.append(c.get_aabb())
	var k := grids.size()
	return func(p: Vector3) -> bool:
		RockNode.inside_calls += 1
		var q := inv * p
		for i in k:
			if bxs[i].has_point(q) and grids[i].contains(q):
				return true
		return false


