## (SolidGrid.near: the voxel grid's dilation); a looser "near" than the box, never a wrong "far".
static func near_fn(cells: Array, inv: Transform3D) -> Callable:
	var grids: Array[SolidGrid] = []
	for c: CpuMesh in cells:
		grids.append(SolidGrid.of(c))
	var k := grids.size()
	var sc := inv.basis.get_scale()
	var grow := maxf(absf(sc.x), maxf(absf(sc.y), absf(sc.z)))   # world m -> the cells' m (at most)
	return func(p: Vector3, m: float) -> bool:
		var q := inv * p
