# (polish) Where _stand_by(r) puts the player and the flattest flag spot round there (2.5-10.5 m off, not at
# the rock): [spot (xz), its slope, the first spot tried (xz)].
func _flat_round(r: RockNode) -> Array:
	var away := _xz(_me.global_position - r.global_position)
	if away.length() < 0.1:
		away = Vector2(1, 0)
	away = away.normalized()
	var me := _xz(r.global_position) + away * (r.size + 1.0)
	var side := Vector2(-away.y, away.x)
	var first := me + side * 3.0 + away * 0.5
	var best := first
	var flat := _ss.slope_at(_ground_at(Vector3(first.x, 0.0, first.y)))
	if flat <= StoneSystem.PILE_SLOPE * 0.8:
		return [first, flat, first]
	for k in 96:
		var c := me + side.rotated(float(k % 16) * TAU / 16.0) * (2.5 + 1.6 * float(k / 16))
		if c.distance_to(_xz(r.global_position)) < r.size * 0.6 + 1.0:
			continue
		var sl := _ss.slope_at(_ground_at(Vector3(c.x, 0.0, c.y)))
		if sl < flat:
			flat = sl
			best = c
		if flat <= StoneSystem.PILE_SLOPE * 0.6:
			break
	return [best, flat, first]


# One RMB press and release (the server sees the edge), whatever it does.
func _key_rmb_once() -> void:
	_me.input_sender.set_meta("x", 0)
	await _rmb_raw()
'''
