func _flag_spot(side: Vector2) -> Vector3:
	var eye := _me.camera.global_position
	var me := _xz(_me.global_position)
	var fallback := _ground_at(Vector3(me.x + side.x * 3.0, 0.0, me.y + side.y * 3.0))
